public void Encode(RlpStream rlpStream, TxReceipt item, RlpBehaviors rlpBehaviors = RlpBehaviors.None)
{
    if (item is null) { rlpStream.EncodeNullObject(); return; }

    (int totalContentLength, int logsLength) = GetContentLength(item, rlpBehaviors);
    int sequenceLength = Rlp.LengthOfSequence(totalContentLength);
    bool isEip658Receipts = (rlpBehaviors & RlpBehaviors.Eip658Receipts) == RlpBehaviors.Eip658Receipts;

    if (item.TxType != TxType.Legacy)
    {
        if ((rlpBehaviors & RlpBehaviors.SkipTypedWrapping) == RlpBehaviors.None)
        {
            rlpStream.StartByteArray(sequenceLength + 1, false);
        }
        rlpStream.WriteByte((byte)item.TxType);  // type prefix byte
    }
    rlpStream.StartSequence(totalContentLength);
    // ... StatusCode or PostTransactionState, GasUsedTotal, Bloom, Logs
}

// PRIMARY: src/Nethermind/Nethermind.Serialization.Rlp/ReceiptMessageDecoder.cs:ReceiptMessageDecoder/Encode (lines 145-192)
