        txReceipt.TxType = (TxType)ctx.ReadByte();  // type byte read here, no validation against {1,2,3,4}
    }
    // ... no assert/range check on TxType value
    _ = ctx.ReadSequenceLength();
    // ... reads firstItem, GasUsedTotal, Bloom, Logs
}

