// PRIMARY: src/Nethermind/Nethermind.Consensus/Validators/TxValidator.cs:BlobFieldsTxValidator/ValidateBlobGasLimits (lines 228-247)
internal static ValidationResult ValidateBlobGasLimits(int txBlobCount, IReleaseSpec spec)
{
    if (txBlobCount < Eip4844Constants.MinBlobsPerTransaction)
        return TxErrorMessages.BlobTxMissingBlobs;

    ulong txBlobGas = BlobGasCalculator.CalculateBlobGas(txBlobCount);
    ulong maxBlobGasPerBlock = spec.GetMaxBlobGasPerBlock();
    if (txBlobGas > maxBlobGasPerBlock)  // gas limit checked here
        return BlockErrorMessages.BlobGasUsedAboveBlockLimit(...);

    ulong maxBlobGasPerTx = spec.GetMaxBlobGasPerTx();
    return txBlobGas > maxBlobGasPerTx ? TxErrorMessages.BlobTxGasLimitExceeded(...) : ValidationResult.Success;
}

// PRIMARY: src/Nethermind/Nethermind.Consensus/Validators/TxValidator.cs:BlobFieldsTxValidator/ValidateBlobFields (lines 204-226)
private static ValidationResult ValidateBlobFields(Transaction transaction, IReleaseSpec spec)
{
    int blobCount = transaction.BlobVersionedHashes!.Length;
    ValidationResult blobPerTxLimitValidationResult = ValidateBlobGasLimits(blobCount, spec);
    if (!blobPerTxLimitValidationResult) return blobPerTxLimitValidationResult;

    for (int i = 0; i < blobCount; i++)  // iterates, returns on first invalid hash
    {
        switch (transaction.BlobVersionedHashes[i])
        {
            case null: return TxErrorMessages.MissingBlobVersionedHash;  // short-circuit on first invalid
            case { Length: not KzgPolynomialCommitments.BytesPerBlobVersionedHash }: return TxErrorMessages.InvalidBlobVersionedHashSize;
            case { ... } when ... != KzgBlobHashVersionV1: return TxErrorMessages.InvalidBlobVersionedHashVersion;
        }
    }
    return ValidationResult.Success;
}

